export class PCMPlayer {
 constructor(onState){this.onState=onState;this.sources=new Set();this.context=null;this.generation=0;this.odd=null;this.endAt=0;this.timer=null;this.started=false}
 async unlock(){this.context??=new AudioContext({sampleRate:24000});await this.context.resume()}
 stop(){this.generation++;clearTimeout(this.timer);for(const s of this.sources){try{s.stop()}catch{}}this.sources.clear();this.endAt=0;this.odd=null;this.started=false;this.onState('stopped')}
 async push(bytes){const generation=this.generation;await this.unlock();if(generation!==this.generation)return;let input=bytes;if(this.odd!==null)input=[this.odd,...input];this.odd=input.length%2?input[input.length-1]:null;const length=Math.floor(input.length/2);if(!length)return;const buf=this.context.createBuffer(1,length,24000),samples=buf.getChannelData(0);for(let i=0;i<length;i++){let v=input[2*i]|input[2*i+1]<<8;if(v>=32768)v-=65536;samples[i]=v/32768}const source=this.context.createBufferSource();source.buffer=buf;source.connect(this.context.destination);const at=Math.max(this.context.currentTime+.025,this.endAt);this.endAt=at+buf.duration;this.sources.add(source);source.onended=()=>this.sources.delete(source);source.start(at);if(!this.started){this.started=true;setTimeout(()=>{if(generation===this.generation)this.onState('playing')},Math.max(0,(at-this.context.currentTime)*1000))}}
 finish(done){const generation=this.generation;clearTimeout(this.timer);this.timer=setTimeout(()=>{if(generation!==this.generation)return;this.started=false;this.onState('ended');done()},Math.max(0,((this.endAt||0)-(this.context?.currentTime||0))*1000)+80)}
}
export function resample(samples,fromRate,toRate=16000){if(fromRate===toRate)return samples;const ratio=fromRate/toRate,out=new Float32Array(Math.floor(samples.length/ratio));for(let i=0;i<out.length;i++){const lo=Math.floor(i*ratio),hi=Math.max(lo+1,Math.floor((i+1)*ratio));let sum=0;for(let j=lo;j<hi&&j<samples.length;j++)sum+=samples[j];out[i]=sum/(hi-lo)}return out}
export function wav(samples,rate){const buffer=new ArrayBuffer(44+samples.length*2),v=new DataView(buffer);const str=(offset,s)=>{for(let i=0;i<s.length;i++)v.setUint8(offset+i,s.charCodeAt(i))};str(0,'RIFF');v.setUint32(4,36+samples.length*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,samples.length*2,true);samples.forEach((x,i)=>v.setInt16(44+i*2,Math.max(-1,Math.min(1,x))*32767,true));return Array.from(new Uint8Array(buffer))}
export class VoiceCapture {
 constructor({onStart,onTurn,onLevel,onError}){Object.assign(this,{onStart,onTurn,onLevel,onError});this.active=false;this.speaking=false;this.frames=[];this.pre=[];this.silent=0;this.voiced=0;this.total=0;this.hot=0}
 async start(){try{this.stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});this.ctx=new AudioContext();await this.ctx.audioWorklet.addModule('./audio-worklet.js');this.source=this.ctx.createMediaStreamSource(this.stream);this.node=new AudioWorkletNode(this.ctx,'nova-capture');this.mute=this.ctx.createGain();this.mute.gain.value=0;this.source.connect(this.node).connect(this.mute).connect(this.ctx.destination);this.node.port.onmessage=e=>this.frame(e.data);this.active=true}catch(e){this.stop();throw e}}
 frame(samples){if(!this.active)return;const dt=samples.length/this.ctx.sampleRate,rms=Math.sqrt(samples.reduce((s,x)=>s+x*x,0)/samples.length);this.onLevel(rms);const voiced=rms>.022;if(!this.speaking){this.pre.push(samples);while(this.pre.length>Math.ceil(this.ctx.sampleRate*.2/128))this.pre.shift();this.hot=voiced?this.hot+dt:0;if(this.hot>.075){this.speaking=true;this.frames=this.pre.slice();this.pre=[];this.voiced=0;this.total=0;this.silent=0;this.onStart()}return}this.frames.push(samples);this.total+=dt;if(voiced){this.voiced+=dt;this.silent=0}else this.silent+=dt;if(this.silent>.7||this.total>20){const frames=this.frames;this.frames=[];this.speaking=false;this.hot=0;if(this.voiced<.12)return;const joined=new Float32Array(frames.reduce((n,x)=>n+x.length,0));let pos=0;for(const f of frames){joined.set(f,pos);pos+=f.length}this.onTurn(wav(resample(joined,this.ctx.sampleRate),16000)).catch(this.onError)}}
 stop(){this.active=false;this.stream?.getTracks().forEach(t=>t.stop());this.node?.disconnect();this.source?.disconnect();this.ctx?.close();this.speaking=false;this.frames=[];this.pre=[];this.hot=0}
}
